const mysql=require("mysql2/promise"),dbConfig={host:"localhost",user:"root",password:"",database:"pozitif_klinik",charset:"utf8mb4"};async function migrateSpecialties(){try{const a=await mysql.createConnection(dbConfig);await a.query("DROP TABLE IF EXISTS sys_specialty_forms"),await a.query("\n            CREATE TABLE IF NOT EXISTS sys_medical_specialties (\n              id int(10) unsigned NOT NULL AUTO_INCREMENT,\n              code varchar(50) NOT NULL,\n              name varchar(100) NOT NULL,\n              icd_prefixes varchar(255) DEFAULT NULL COMMENT 'Comma separated ICD-10 prefixes for search boost',\n              form_schema LONGTEXT DEFAULT NULL,\n              is_active tinyint(1) DEFAULT 1,\n              created_at timestamp NOT NULL DEFAULT current_timestamp(),\n              PRIMARY KEY (id),\n              UNIQUE KEY specialty_code (code)\n            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n        ");const i=[["INTERNAL_MEDICINE","İç Hastalıkları (Dahiliye)","A,B,E,J,I,N"],["CARDIOLOGY","Kardiyoloji","I"],["ENT","Kulak Burun Boğaz","H,J"],["OPHTHALMOLOGY","Göz Hastalıkları","H"],["ORTHOPEDICS","Ortopedi ve Travmatoloji","M"],["DERMATOLOGY","Dermatoloji (Cildiye)","L"],["NEUROLOGY","Nöroloji","G"],["PSYCHIATRY","Psikiyatri","F"],["GYNECOLOGY","Kadın Hastalıkları ve Doğum","O"],["PEDIATRICS","Çocuk Sağlığı ve Hastalıkları","A,B,E,J,P,Q"],["UROLOGY","Üroloji","N"],["GENERAL_SURGERY","Genel Cerrahi","K,C,D"],["PULMONOLOGY","Göğüs Hastalıkları","J"],["ENDOCRINOLOGY","Endokrinoloji","E"],["INFECTIOUS_DISEASES","Enfeksiyon Hastalıkları","A,B"],["EMERGENCY","Acil Tıp","R,S,T"]];for(const[e,t,s]of i)await a.query("INSERT IGNORE INTO sys_medical_specialties (code, name, icd_prefixes) VALUES (?, ?, ?)",[e,t,s]);a.end()}catch(a){}}migrateSpecialties();